// Extract text from the file Google Drive downloaded. Dispatches on mime
// type:
//   - .docx (wordprocessingml.document) → mammoth.extractRawText() unzips
//     the OOXML archive and pulls the paragraph text out cleanly.
//   - text/* or .txt/.md → UTF-8 decode of the raw buffer.
//   - anything else → UTF-8 attempt with a decode_error flag for triage.
// n8n's binary storage may be filesystem-backed, so we go through the
// helpers.getBinaryDataBuffer accessor regardless of storage mode.
const item = $input.first();
const meta = (item.binary && item.binary.data) || {};
const mime = (meta.mimeType || '').toLowerCase();
const fileName = meta.fileName || '';
const ext = (meta.fileExtension || fileName.split('.').pop() || '').toLowerCase();

let text = '';
let decodeError = '';
let decodePath = '';

try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  if (mime.includes('wordprocessingml.document') || ext === 'docx') {
    const mammoth = require('mammoth');
    const result = await mammoth.extractRawText({ buffer: buf });
    text = result.value || '';
    decodePath = 'mammoth';
    if ((result.messages || []).length > 0) {
      decodeError = result.messages.map((m) => m.message).join('; ');
    }
  } else if (mime.startsWith('text/') || ['txt','md','markdown','log'].includes(ext)) {
    text = buf.toString('utf-8');
    decodePath = 'utf-8 (text)';
  } else if (mime.includes('vnd.google-apps.document')) {
    decodeError = 'Source is a native Google Doc — change Download Transcript to use the Export operation with text/plain mime type.';
    decodePath = 'unsupported-google-doc';
  } else {
    text = buf.toString('utf-8');
    decodePath = 'utf-8 (fallback)';
    if (/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(text.substring(0, 500))) {
      decodeError = 'Unknown mime ' + mime + ' (ext=' + ext + ') — decoded as UTF-8 but result looks binary. Add a handler for this format.';
    }
  }
} catch (e) {
  decodeError = e && e.message || String(e);
}

text = text.replace(/\u0000/g, '').trim().substring(0, 20000);
const source = item.json || {};
return [{
  json: {
    transcript: text,
    transcript_length: text.length,
    decode_path: decodePath,
    decode_error: decodeError,
    source_file_id: source.id,
    source_file_name: source.name,
    source_mime_type: meta.mimeType || '',
  },
}];

// Build the Gemma 4 prompt for the Scribe. Asks for a STRUCTURED ticket:
// markdown description with named sections, an inferred ticket type from
// Switchyard's enum, and extracted custom-field hints. Lighter prompt
// variants (e.g. "cleaned-up version") cause Gemma 4 to produce a
// single prose paragraph — that's the failure mode we're fixing here.
const extract = $('Extract Text').first().json;
const transcript = extract.transcript || '';
const projects = ($('List Switchyard Projects').first().json.items) || [];

const projectList = projects.map((p) =>
  '- ' + p.key + ' — ' + p.name + (p.description ? ': ' + p.description.substring(0, 150) : '')
).join('\n');

const prompt =
  'You are a senior engineer turning a raw voice transcript into a clean, structured Switchyard ticket. Rewrite — do not paraphrase. Output JSON ONLY.\n\n' +
  'PROJECT ROUTING (critical — `project_key` is immutable after ticket creation):\n' +
  '- Pick the BEST MATCH from the projects listed below based on what the transcript talks about.\n' +
  '- If you cannot tell which project applies, return empty string "" for project_key — DO NOT default to one.\n' +
  '- Project keys are case-sensitive (always uppercase).\n\n' +
  'Available projects:\n' + projectList + '\n\n' +
  'TYPE (Switchyard enum, pick ONE):\n' +
  '- "spike"  — research/investigation/spike work; outcome is learning, not shipped code\n' +
  '- "task"   — default; a discrete piece of work\n' +
  '- "bug"    — fixing something broken\n' +
  '- "epic"   — large multi-piece initiative that will spawn child tickets\n\n' +
  'TITLE: imperative, action-oriented, max 100 chars, no marketing fluff.\n\n' +
  'DESCRIPTION format (markdown, REQUIRED sections in this order, no extra preamble):\n' +
  '## Summary\n' +
  '1-2 sentences describing what the ticket is about, written as if by a senior engineer (not transcribed).\n\n' +
  '## Goals\n' +
  '- Bullet list of what the work should accomplish. Each bullet is concrete and testable. Strip filler.\n\n' +
  '## Approach\n' +
  '- Bullets describing HOW (if the transcript suggests an approach). If the transcript only describes WHAT, write: "_TBD — surface during planning._"\n\n' +
  '## Open questions\n' +
  '- Bullets of unresolved questions raised by the transcript. OMIT this entire section (no header) if there are none.\n\n' +
  'Rules: NO disfluencies (um/uh/like). NO filler ("basically", "kinda"). Fix speech-to-text errors based on context (e.g. "field or an injury" → "field or section" when context is clear). DO NOT invent details the transcript does not support. Preserve all concrete requirements. PRESERVE actor distinctions verbatim: if the transcript says "agents" do NOT silently rewrite to "users" (or vice versa); the difference between human-driven and agent-driven affects planning.\n\n' +
  'Other fields:\n' +
  '- mode: "modify" (change to existing repo), "scaffold" (new project from template), or "greenfield" (open-ended creation requiring agent iteration). For changes to an existing project that has a known repo, use "modify".\n' +
  '- repo_url: GitHub URL ONLY if explicitly mentioned in the transcript. Otherwise empty. NEVER invent a URL.\n' +
  '- test_cmd: shell test command ONLY if explicitly mentioned. Otherwise empty.\n' +
  '- template: "vue" | "go" | "node" if scaffold and clear. Otherwise empty.\n' +
  '- scaffold_project: kebab-case name if scaffold. Otherwise empty.\n\n' +
  'Respond with EXACT JSON ONLY (no markdown fences):\n' +
  '{"project_key":"","type":"","title":"","description":"","mode":"","repo_url":"","test_cmd":"","template":"","scaffold_project":""}\n\n' +
  'Transcript:\n' + transcript;

const scribeBody = JSON.stringify({
  model: 'gemma4:31b',
  stream: false,
  format: 'json',
  prompt,
});

return [{ json: { scribe_body: scribeBody, transcript_length: transcript.length } }];

// Parse Gemma 4's JSON, validate project_key against the live project list,
// and build the Switchyard CreateTicket body. When project inference is
// uncertain we fall back to LOOP and flag the ticket so a human can triage —
// project_key is immutable, so we accept the cost of moving via delete+recreate
// in exchange for never blocking the pipeline.
const llmRaw = $input.first().json.response || '';
let parsed = {};
try {
  parsed = typeof llmRaw === 'string' ? JSON.parse(llmRaw) : llmRaw;
} catch (e) {
  const match = (llmRaw || '').match(/```json?\s*([\s\S]*?)```/);
  if (match) { try { parsed = JSON.parse(match[1]); } catch (e2) {} }
}

const projects = ($('List Switchyard Projects').first().json.items) || [];
const allowed = projects.map((p) => p.key);

let projectKey = (parsed.project_key || '').toUpperCase().trim();
let projectFallback = false;
let fallbackReason = '';
if (!projectKey) {
  projectKey = 'LOOP';
  projectFallback = true;
  fallbackReason = 'Scribe returned empty project_key (transcript context was unclear).';
} else if (!allowed.includes(projectKey)) {
  fallbackReason = 'Scribe returned project_key="' + projectKey + '" which is not in the live project list.';
  projectKey = 'LOOP';
  projectFallback = true;
}

const allowedTypes = ['spike', 'task', 'bug', 'epic'];
let ticketType = (parsed.type || '').toLowerCase().trim();
if (!allowedTypes.includes(ticketType)) ticketType = 'task';
const title = (parsed.title || 'Untitled voice note').toString().substring(0, 500);
const mode = (parsed.mode || 'modify').toLowerCase();
const metadata = { mode };
if (parsed.repo_url) metadata.repo_url = parsed.repo_url;
if (parsed.test_cmd) metadata.test_cmd = parsed.test_cmd;
if (parsed.template) metadata.template = parsed.template;
if (parsed.scaffold_project) metadata.scaffold_project = parsed.scaffold_project;

const descriptionLines = [
  (parsed.description || '').toString(),
];
if (parsed.repo_url) descriptionLines.push('repo: ' + parsed.repo_url);
if (parsed.test_cmd) descriptionLines.push('test_cmd: ' + parsed.test_cmd);
if (parsed.template) descriptionLines.push('template: ' + parsed.template);
if (parsed.scaffold_project) descriptionLines.push('project: ' + parsed.scaffold_project);
const description = descriptionLines.filter(Boolean).join('\n\n');

const ticketBody = JSON.stringify({
  project_key: projectKey,
  type: ticketType,
  title,
  description,
  metadata,
});

const triageBody = projectFallback
  ? JSON.stringify({
      body:
        ':warning: **Project routing fell back to LOOP** — needs human triage.\n\n' +
        fallbackReason + '\n\n' +
        'If this ticket belongs to a different project, please delete it and recreate manually ' +
        '(project_key is immutable on Switchyard tickets). Re-train the Scribe by clarifying the transcript next time.',
    })
  : '';


// Idempotency-Key fingerprint: same Drive file + same inferred routing +
// same title → same ticket (legitimate retry replays). Re-parsing the same
// file with a different project_key (e.g. after fixing decode) treats it
// as a fresh request and creates a new ticket.
const slugify = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').substring(0, 40);
let _h = 0;
const _fpInput = projectKey + '|' + title + '|' + mode;
for (let i = 0; i < _fpInput.length; i++) _h = ((_h << 5) - _h + _fpInput.charCodeAt(i)) | 0;
const fingerprint = Math.abs(_h).toString(36) + '-' + slugify(title).substring(0, 20);

return [{
  json: {
    ticket_body: ticketBody,
    triage_body: triageBody,
    project_key: projectKey,
    project_fallback: projectFallback,
    parsed_title: title,
    parsed_mode: mode,
    parsed_type: ticketType,
    idempotency_fingerprint: fingerprint,
  },
}];
